import hashlib,json,sys
from pathlib import Path
base=Path(__file__).resolve().parent;task=sys.argv[1];run=base/'solvers'/task;gold=json.loads((base/'source-gold-reviewed.json').read_text());spec=next(t for t in gold['tasks'] if t['id']==task);reviews=base/'reviews';reviews.mkdir(exist_ok=True)
packet={'task':spec,'scoring':gold['scoring'],'scope_guards':gold['scope_guards'],'answer_path':str(run/'answer.md'),'answer_sha256':hashlib.sha256((run/'answer.md').read_bytes()).hexdigest(),'views_directory':str(run/'views'),'display_coverage':json.loads((base/'view-coverage.json').read_text())['tasks'][task],'source_root':str(base.parent/'capture-input/CleanArchitecture'),'build_variant':'Debug/net10.0, no custom DefineConstants','run_accounting':json.loads((run/'state.json').read_text()),'execution_record':next(x for x in json.loads((base/'execution.json').read_text())['runs'] if x['task']==task),'instructions':'Read exact answer and logged displayed evidence. Independently assess each atom against source. Do not equate retained raw response with inspected evidence. Distinguish material unsupported claims from minor citation imprecision. Preserve correct partial credit. Do not inspect product implementation, other reviews, other solver runs or query products.'}
(reviews/(task+'.packet.json')).write_text(json.dumps(packet,indent=2)+'\n')
prompt=f'''You are a fresh independent answer reviewer. Work alone; no agents. Read {reviews/(task+'.packet.json')}. Inspect the specified answer, relevant displayed view records, frozen source and rubric only. No product queries, product implementation, other task answers or other reviews. Verify answer SHA. Assess all {len(spec['atoms'])} atoms, allowing equivalent exact citations.\n\nWrite JSON to {reviews/(task+'.independent.json')} with: task, answer_sha256, atoms (id, correctness 0/0.5/1, evidence 0/0.5/1, reason, answer_citations, inspected_evidence), material_unsupported_claims (array), minor_issues (array), runtime_distinction_preserved (boolean), strict_success (all atom scores 1 and no material unsupported claims and runtime distinction and budget compliance), independence_attestation. Score evidence from source supporting the claim and actually displayed through views; view files are JSON envelopes with selected data fragments. You may parse/join contiguous fragments and compare ranges. Do not demand whole-response reading when complete relevant fields were displayed. Do not penalize optional task scope.\n\nAccount for instruction-based isolation: transcript/attestation evidence supports compliance, but cannot establish OS-enforced separation or model attention. Report missing display evidence rather than inventing it. Return concise scores and major findings.\n'''
(reviews/(task+'.prompt.txt')).write_text(prompt);print(str(reviews/(task+'.prompt.txt')))
